DO $$
DECLARE
  kind text;
BEGIN
  SELECT relkind::text INTO kind FROM pg_class WHERE oid = to_regclass('v2."V2Blob"');
  IF kind IS NULL THEN
    RETURN;
  END IF;
  IF kind <> 'v' THEN
    RAISE EXCEPTION 'refusing to drop %.%: relkind % is not a view', 'v2', 'V2Blob', kind;
  END IF;
  EXECUTE 'DROP VIEW v2."V2Blob"';
END
$$

